import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export type Role = 'user' | 'assistant';

export interface Message {
  id: string;
  role: Role;
  content: string;
  timestamp: Date;
}

export interface GeminiResponse {
  text: string;
  error?: string;
}

import { GoogleGenAI } from "@google/genai";
import { GeminiResponse } from "../types";

const SYSTEM_INSTRUCTION = `You are a wise and compassionate Bible scholar. 
Provide answers based strictly on Bible teachings. 
Your responses MUST be extremely concise, strictly no more than 10 words. 
Focus on the core spiritual truth and wisdom. 
Do not include references unless essential to the 10-word limit.`;

export const getBibleWisdom = async (prompt: string): Promise<GeminiResponse> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        temperature: 0.7,
        topK: 40,
        topP: 0.95,
      },
    });

    const text = response.text || "I could not find a scriptural answer.";
    return { text };
  } catch (error) {
    console.error("Gemini API Error:", error);
    return { 
      text: "Apologies, a connection to wisdom was interrupted.",
      error: error instanceof Error ? error.message : "Unknown error"
    };
  }
};

import React from 'react';
import { Message } from '../types';

