      <div className={`flex max-w-[85%] md:max-w-[70%] ${isUser ? 'flex-row-reverse' : 'flex-row'} gap-3`}>
        <div className={`flex-shrink-0 w-8 h-8 rounded-full flex items-center justify-center text-xs font-bold shadow-sm ${
          isUser ? 'bg-indigo-600 text-white' : 'bg-amber-100 text-amber-700'
        }`}>
          {isUser ? <i className="fa-solid fa-user"></i> : <i className="fa-solid fa-dove"></i>}
        </div>

        <div className={`flex flex-col ${isUser ? 'items-end' : 'items-start'}`}>
          <div className={`px-4 py-3 rounded-2xl text-sm leading-relaxed shadow-sm relative group ${
            isUser 
              ? 'bg-indigo-600 text-white rounded-tr-none' 
              : 'bg-white text-slate-800 rounded-tl-none border border-slate-100'
          }`}>
            {message.content}

            {!isUser && message.metadata && (
              <div className="mt-2 pt-2 border-t border-slate-50 flex justify-between items-center gap-4">
                <span className="text-[10px] font-bold text-indigo-600 italic">
                  — {message.metadata.reference}
                </span>
                {onSave && (
                  <button 
                    onClick={() => onSave(message)}
                    className={`text-xs transition-colors p-1 rounded-full ${isSaved ? 'text-rose-500' : 'text-slate-300 hover:text-rose-400'}`}
                    title={isSaved ? "Saved to favorites" : "Save to favorites"}
                  >
                    <i className={`fa-${isSaved ? 'solid' : 'regular'} fa-heart`}></i>
                  </button>
                )}
              </div>
            )}
          </div>
          <span className="text-[10px] text-slate-400 mt-1 uppercase tracking-wider font-medium flex items-center gap-2">
            {message.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
            {!isUser && message.metadata && (
              <span className="bg-slate-100 px-1.5 py-0.5 rounded text-[9px] text-slate-500 border border-slate-200 uppercase font-bold tracking-tighter">
                {message.metadata.topic}
              </span>
            )}
          </span>
        </div>
      </div>
    </div>
  );
};

export default ChatMessage;

import React, { useState, useRef, useEffect } from 'react';
import { Message, SavedAnswer } from './types';
import { getBibleWisdom } from './services/geminiService';
import ChatMessage from './components/ChatMessage';

const App: React.FC = () => {
  const [messages, setMessages] = useState<Message[]>([
    {
      id: 'welcome',
      role: 'assistant',
      content: 'Welcome. What spiritual wisdom do you seek today?',
      timestamp: new Date()
    }
  ]);
  const [savedAnswers, setSavedAnswers] = useState<SavedAnswer[]>([]);
  const [showFavorites, setShowFavorites] = useState(false);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  // Load favorites from local storage
  useEffect(() => {
    const stored = localStorage.getItem('bible_favorites');
    if (stored) {
      try {
        const parsed = JSON.parse(stored);
        setSavedAnswers(parsed.map((item: any) => ({
          ...item,
          timestamp: new Date(item.timestamp)
        })));
      } catch (e) {
        console.error("Failed to parse favorites", e);
      }
    }
  }, []);

  // Save favorites to local storage
  useEffect(() => {
    localStorage.setItem('bible_favorites', JSON.stringify(savedAnswers));
  }, [savedAnswers]);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const toggleFavorite = (message: Message) => {
    if (!message.metadata) return;

    const existingIndex = savedAnswers.findIndex(s => s.id === message.id);
    if (existingIndex > -1) {
      setSavedAnswers(prev => prev.filter((_, i) => i !== existingIndex));
    } else {
      const userMsg = messages.find((m, i) => messages[i+1]?.id === message.id && m.role === 'user');
      const newFavorite: SavedAnswer = {
        id: message.id,
        question: userMsg?.content || "Spiritual Question",
        answer: message.content,
        reference: message.metadata.reference,
        topic: message.metadata.topic,
        timestamp: new Date()
      };
      setSavedAnswers(prev => [newFavorite, ...prev]);
    }
  };

  const removeFavorite = (id: string) => {
    setSavedAnswers(prev => prev.filter(s => s.id !== id));
  };

  const handleSend = async (e?: React.FormEvent) => {
    e?.preventDefault();
    if (!input.trim() || isLoading) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: input,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMessage]);
    const currentInput = input;
    setInput('');
    setIsLoading(true);

    try {
      const result = await getBibleWisdom(currentInput);
      const assistantMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: result.answer,
        timestamp: new Date(),
        metadata: {
          reference: result.reference,
          topic: result.topic
        }
      };
      setMessages(prev => [...prev, assistantMessage]);
    } catch (error) {
      console.error(error);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#f0f2f5]">
      {/* Header */}
      <header className="sticky top-0 z-50 glass shadow-sm h-16 flex items-center px-6">
        <div className="max-w-4xl mx-auto w-full flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-indigo-200">
              <i className="fa-solid fa-book-bible text-lg"></i>
            </div>
            <div>
              <h1 className="font-serif text-xl font-bold text-slate-800">BibleWisdom</h1>
              <p className="text-[10px] uppercase tracking-widest text-indigo-600 font-bold">Divine Insights</p>
            </div>
          </div>
          <button 
            onClick={() => setShowFavorites(true)}
            className="relative flex items-center gap-2 px-4 py-2 bg-white border border-slate-200 rounded-xl text-slate-600 text-sm font-semibold hover:bg-slate-50 transition-all shadow-sm active:scale-95"
          >
            <i className="fa-solid fa-heart text-rose-500"></i>
            Saved
            {savedAnswers.length > 0 && (
              <span className="absolute -top-1 -right-1 w-5 h-5 bg-rose-500 text-white text-[10px] flex items-center justify-center rounded-full border-2 border-white font-bold">
                {savedAnswers.length}
              </span>
            )}
          </button>
        </div>
      </header>

      {/* Main Chat Area */}
      <main className="flex-1 overflow-hidden relative flex flex-col">
        <div className="flex-1 overflow-y-auto px-4 py-8">
          <div className="max-w-4xl mx-auto flex flex-col">
            {messages.map((msg) => (
              <ChatMessage 
                key={msg.id} 
                message={msg} 
                onSave={toggleFavorite}
                isSaved={savedAnswers.some(s => s.id === msg.id)}
              />
            ))}
            {isLoading && (
              <div className="flex justify-start mb-6 animate-pulse">
                <div className="bg-white border border-slate-100 px-4 py-3 rounded-2xl rounded-tl-none flex items-center gap-2">
                  <div className="w-1.5 h-1.5 bg-slate-400 rounded-full animate-bounce"></div>
                  <div className="w-1.5 h-1.5 bg-slate-400 rounded-full animate-bounce delay-75"></div>
                  <div className="w-1.5 h-1.5 bg-slate-400 rounded-full animate-bounce delay-150"></div>
                </div>
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>
        </div>

        {/* Input Bar */}
        <div className="p-4 bg-transparent">
          <div className="max-w-4xl mx-auto">
            <form 
              onSubmit={handleSend}
              className="relative flex items-center gap-2"
            >
              <div className="relative flex-1 group">
                <input
                  type="text"
                  value={input}
                  onChange={(e) => setInput(e.target.value)}
                  placeholder="Ask for biblical wisdom..."
                  className="w-full bg-white border-2 border-slate-200 focus:border-indigo-500 focus:ring-0 rounded-2xl py-4 pl-6 pr-14 text-sm transition-all duration-200 shadow-md group-hover:shadow-lg outline-none"
                  disabled={isLoading}
                />
                <button
                  type="submit"
                  disabled={!input.trim() || isLoading}
                  className={`absolute right-3 top-1/2 -translate-y-1/2 w-10 h-10 rounded-xl flex items-center justify-center transition-all duration-200 ${
                    input.trim() && !isLoading 
                    ? 'bg-indigo-600 text-white scale-100 shadow-lg shadow-indigo-200 hover:bg-indigo-700' 
                    : 'bg-slate-100 text-slate-400 scale-90'
                  }`}
                >
                  <i className={`fa-solid ${isLoading ? 'fa-spinner fa-spin' : 'fa-paper-plane'}`}></i>
                </button>
              </div>
            </form>
            <p className="text-center text-[10px] text-slate-400 mt-3 font-medium uppercase tracking-tighter">
              Seek and you shall find &bull; All answers in 10 words or less
            </p>
          </div>
        </div>
      </main>

      {/* Favorites Modal Overlay */}
      {showFavorites && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm" onClick={() => setShowFavorites(false)}></div>
          <div className="relative bg-white w-full max-w-lg rounded-3xl shadow-2xl flex flex-col max-h-[80vh] overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-6 border-b border-slate-100 flex items-center justify-between">
              <div className="flex items-center gap-3">
                <i className="fa-solid fa-heart text-rose-500 text-xl"></i>
                <h2 className="font-serif text-xl font-bold text-slate-800">Saved Wisdom</h2>
              </div>
              <button 
                onClick={() => setShowFavorites(false)}
                className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-slate-100 text-slate-400 transition-colors"
              >
                <i className="fa-solid fa-xmark"></i>
              </button>
            </div>

            <div className="flex-1 overflow-y-auto p-6 space-y-6">
              {savedAnswers.length === 0 ? (
                <div className="text-center py-12">
                  <div className="w-16 h-16 bg-slate-50 text-slate-200 rounded-full flex items-center justify-center mx-auto mb-4">
                    <i className="fa-solid fa-bookmark text-3xl"></i>
                  </div>
                  <p className="text-slate-400 font-medium">No saved items yet.</p>
                  <p className="text-xs text-slate-300 mt-1 uppercase tracking-widest">Your favorite verses will appear here</p>
                </div>
              ) : (
                savedAnswers.map((item) => (
                  <div key={item.id} className="group relative bg-slate-50 rounded-2xl p-4 border border-slate-100 hover:border-indigo-100 transition-all hover:shadow-md">
                    <div className="flex justify-between items-start mb-2">
                      <span className="text-[10px] font-bold text-indigo-600 bg-indigo-50 px-2 py-0.5 rounded uppercase tracking-wider">
                        {item.topic}
                      </span>
                      <button 
                        onClick={() => removeFavorite(item.id)}
                        className="text-slate-300 hover:text-rose-500 transition-colors p-1"
                      >
                        <i className="fa-solid fa-trash-can text-xs"></i>
                      </button>
                    </div>
                    <p className="text-xs text-slate-500 italic mb-2">"{item.question}"</p>
                    <p className="text-slate-800 font-medium leading-relaxed mb-1">
                      {item.answer}
                    </p>
                    <p className="text-xs font-bold text-slate-400">— {item.reference}</p>
                  </div>
                ))
              )}
            </div>
          </div>
        </div>
      )}

      {/* Decorative background elements */}
      <div className="fixed top-20 left-10 w-64 h-64 bg-indigo-200 rounded-full mix-blend-multiply filter blur-3xl opacity-20 animate-blob"></div>
      <div className="fixed bottom-20 right-10 w-64 h-64 bg-amber-200 rounded-full mix-blend-multiply filter blur-3xl opacity-20 animate-blob animation-delay-2000"></div>
    </div>
  );
};

export default App;

export type Role = 'user' | 'assistant';

export interface Message {
  id: string;
  role: Role;
  content: string;
  timestamp: Date;
  metadata?: {
    reference: string;
    topic: string;
    explanation: string;
  };
}

export interface SavedAnswer {
  id: string;
  question: string;
  answer: string;
  reference: string;
  topic: string;
  explanation: string;
  timestamp: Date;
}

export interface GeminiResponse {
  answer: string;
  reference: string;
