import { GoogleGenAI, Type } from "@google/genai";
import { GeminiResponse } from "../types";

const SYSTEM_INSTRUCTION = `You are a wise and compassionate Bible scholar. 
Provide answers based strictly on Bible teachings. 
The 'answer' field MUST be extremely concise, strictly no more than 10 words. 
The 'reference' should be the specific Bible verse (e.g., John 3:16).
The 'topic' should be a single word or short phrase describing the subject (e.g., Love, Faith, Patience).
The 'explanation' field should provide 2-3 sentences of deeper context, theological meaning, or practical application of the teaching.`;

export const getBibleWisdom = async (prompt: string): Promise<GeminiResponse> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            answer: {
              type: Type.STRING,
              description: "A short answer based on the Bible, maximum 10 words.",
            },
            reference: {
              type: Type.STRING,
              description: "The Bible verse reference.",
            },
            topic: {
              type: Type.STRING,
              description: "A short topic category.",
            },
            explanation: {
              type: Type.STRING,
              description: "A more detailed 2-3 sentence explanation.",
            },
          },
          required: ["answer", "reference", "topic", "explanation"],
        },
        temperature: 0.7,
      },
    });

    const jsonStr = response.text || "{}";
    const result = JSON.parse(jsonStr);

