export type Role = 'user' | 'assistant';

export type BibleVersion = 'NIV' | 'KJV' | 'ESV' | 'NLT' | 'NKJV' | 'NASB';

export interface Message {
  id: string;
  role: Role;
  content: string;
  timestamp: Date;
  metadata?: {
    reference: string;
    topic: string;
    explanation: string;
    version?: BibleVersion;
  };
}

export interface SavedAnswer {
  id: string;
  question: string;
  answer: string;
  reference: string;
  topic: string;
  explanation: string;
  version: BibleVersion;
  timestamp: Date;
}

export interface GeminiResponse {
  answer: string;
  reference: string;
  topic: string;
  explanation: string;
  error?: string;
}

import { GoogleGenAI, Type } from "@google/genai";
import { GeminiResponse, BibleVersion } from "../types";

const getSystemInstruction = (version: BibleVersion) => `You are a wise and compassionate Bible scholar. 
Provide answers based strictly on Bible teachings using the ${version} translation. 
The 'answer' field should be approximately 2 verses in length (roughly 40-60 words). 
The 'reference' should be the specific Bible verse(s) used (e.g., John 3:16-17).
The 'topic' should be a single word or short phrase describing the subject (e.g., Love, Faith, Patience).
The 'explanation' field should provide 2-3 sentences of deeper context, theological meaning, or practical application of the teaching.`;

export const getBibleWisdom = async (prompt: string, version: BibleVersion): Promise<GeminiResponse> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        systemInstruction: getSystemInstruction(version),
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            answer: {
              type: Type.STRING,
              description: `A biblical answer in the ${version} version, approximately 2 verses in length.`,
            },
            reference: {
              type: Type.STRING,
              description: "The Bible verse reference(s).",
            },
            topic: {
              type: Type.STRING,
              description: "A short topic category.",
            },
            explanation: {
              type: Type.STRING,
              description: "A more detailed 2-3 sentence explanation.",
            },
          },
          required: ["answer", "reference", "topic", "explanation"],
        },
        temperature: 0.7,
      },
    });

    const jsonStr = response.text || "{}";
    const result = JSON.parse(jsonStr);

    return {
      answer: result.answer || "I could not find a scriptural answer.",
      reference: result.reference || "Unknown Reference",
      topic: result.topic || "Spiritual Wisdom",
      explanation: result.explanation || "No further explanation available."
    };
  } catch (error) {
    console.error("Gemini API Error:", error);
    return { 
      answer: "Apologies, a connection to wisdom was interrupted.",
      reference: "",
      topic: "Error",
      explanation: "There was an error connecting to the spiritual database.",
      error: error instanceof Error ? error.message : "Unknown error"
    };
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { Message, SavedAnswer, BibleVersion } from './types';
import { getBibleWisdom } from './services/geminiService';
import ChatMessage from './components/ChatMessage';

const BIBLE_VERSIONS: BibleVersion[] = ['NIV', 'KJV', 'ESV', 'NLT', 'NKJV', 'NASB'];

const App: React.FC = () => {
  const [messages, setMessages] = useState<Message[]>([
    {
      id: 'welcome',
      role: 'assistant',
      content: 'Welcome. What spiritual wisdom do you seek today?',
      timestamp: new Date()
    }
  ]);
  const [savedAnswers, setSavedAnswers] = useState<SavedAnswer[]>([]);
  const [bibleVersion, setBibleVersion] = useState<BibleVersion>('NIV');
  const [showFavorites, setShowFavorites] = useState(false);
  const [expandedSavedId, setExpandedSavedId] = useState<string | null>(null);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  // Load state from local storage
  useEffect(() => {
    const storedFavorites = localStorage.getItem('bible_favorites');
    if (storedFavorites) {
      try {
        const parsed = JSON.parse(storedFavorites);
        setSavedAnswers(parsed.map((item: any) => ({
          ...item,
          timestamp: new Date(item.timestamp)
        })));
      } catch (e) {
        console.error("Failed to parse favorites", e);
      }
    }

    const storedVersion = localStorage.getItem('bible_version');
    if (storedVersion && BIBLE_VERSIONS.includes(storedVersion as BibleVersion)) {
      setBibleVersion(storedVersion as BibleVersion);
    }
  }, []);

  // Persist state to local storage
  useEffect(() => {
    localStorage.setItem('bible_favorites', JSON.stringify(savedAnswers));
  }, [savedAnswers]);

  useEffect(() => {
    localStorage.setItem('bible_version', bibleVersion);
  }, [bibleVersion]);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const toggleFavorite = (message: Message) => {
    if (!message.metadata) return;

    const existingIndex = savedAnswers.findIndex(s => s.id === message.id);
    if (existingIndex > -1) {
      setSavedAnswers(prev => prev.filter((_, i) => i !== existingIndex));
    } else {
      const userMsg = messages.find((m, i) => messages[i+1]?.id === message.id && m.role === 'user');
      const newFavorite: SavedAnswer = {
        id: message.id,
        question: userMsg?.content || "Spiritual Question",
        answer: message.content,
        reference: message.metadata.reference,
        topic: message.metadata.topic,
        explanation: message.metadata.explanation,
        version: message.metadata.version || bibleVersion,
        timestamp: new Date()
      };
      setSavedAnswers(prev => [newFavorite, ...prev]);
    }
  };

  const removeFavorite = (id: string) => {
    setSavedAnswers(prev => prev.filter(s => s.id !== id));
  };

  const handleSend = async (e?: React.FormEvent) => {
    e?.preventDefault();
    if (!input.trim() || isLoading) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: input,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMessage]);
    const currentInput = input;
    const currentVersion = bibleVersion;
    setInput('');
    setIsLoading(true);

    try {
      const result = await getBibleWisdom(currentInput, currentVersion);
      const assistantMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: result.answer,
        timestamp: new Date(),
        metadata: {
          reference: result.reference,
          topic: result.topic,
          explanation: result.explanation,
          version: currentVersion
        }
      };
      setMessages(prev => [...prev, assistantMessage]);
    } catch (error) {
      console.error(error);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#f0f2f5]">
      {/* Header */}
      <header className="sticky top-0 z-50 glass shadow-sm h-16 flex items-center px-4 md:px-6">
        <div className="max-w-4xl mx-auto w-full flex items-center justify-between">
          <div className="flex items-center gap-2 md:gap-3">
            <div className="w-8 h-8 md:w-10 md:h-10 bg-indigo-600 rounded-lg md:rounded-xl flex items-center justify-center text-white shadow-lg shadow-indigo-200">
              <i className="fa-solid fa-book-bible text-sm md:text-lg"></i>
            </div>
            <div className="hidden xs:block">
              <h1 className="font-serif text-lg md:text-xl font-bold text-slate-800">BibleWisdom</h1>
              <p className="text-[8px] md:text-[10px] uppercase tracking-widest text-indigo-600 font-bold">Divine Insights</p>
            </div>
          </div>

          <div className="flex items-center gap-2 md:gap-4">
            {/* Version Selector */}
            <div className="relative group">
              <select 
                value={bibleVersion}
                onChange={(e) => setBibleVersion(e.target.value as BibleVersion)}
                className="appearance-none bg-white border border-slate-200 rounded-xl px-3 py-2 pr-8 text-xs font-bold text-slate-600 shadow-sm focus:outline-none focus:ring-2 focus:ring-indigo-100 transition-all cursor-pointer hover:bg-slate-50"
              >
                {BIBLE_VERSIONS.map(v => <option key={v} value={v}>{v}</option>)}
              </select>
              <div className="absolute right-2 top-1/2 -translate-y-1/2 pointer-events-none text-slate-400 text-[10px]">
                <i className="fa-solid fa-chevron-down"></i>
              </div>
            </div>

            <button 
              onClick={() => setShowFavorites(true)}
              className="relative flex items-center gap-2 px-3 md:px-4 py-2 bg-white border border-slate-200 rounded-xl text-slate-600 text-xs md:text-sm font-semibold hover:bg-slate-50 transition-all shadow-sm active:scale-95"
            >
              <i className="fa-solid fa-heart text-rose-500"></i>
              <span className="hidden sm:inline">Saved</span>
              {savedAnswers.length > 0 && (
                <span className="absolute -top-1 -right-1 w-5 h-5 bg-rose-500 text-white text-[10px] flex items-center justify-center rounded-full border-2 border-white font-bold">
                  {savedAnswers.length}
                </span>
              )}
            </button>
          </div>
        </div>
      </header>

      {/* Main Chat Area */}
      <main className="flex-1 overflow-hidden relative flex flex-col">
        <div className="flex-1 overflow-y-auto px-4 py-8">
          <div className="max-w-4xl mx-auto flex flex-col">
            {messages.map((msg) => (
              <ChatMessage 
                key={msg.id} 
                message={msg} 
                onSave={toggleFavorite}
                isSaved={savedAnswers.some(s => s.id === msg.id)}
              />
            ))}
            {isLoading && (
              <div className="flex justify-start mb-6 animate-pulse">
                <div className="bg-white border border-slate-100 px-4 py-3 rounded-2xl rounded-tl-none flex items-center gap-2">
                  <div className="w-1.5 h-1.5 bg-slate-400 rounded-full animate-bounce"></div>
                  <div className="w-1.5 h-1.5 bg-slate-400 rounded-full animate-bounce delay-75"></div>
                  <div className="w-1.5 h-1.5 bg-slate-400 rounded-full animate-bounce delay-150"></div>
                </div>
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>
        </div>

        {/* Input Bar */}
        <div className="p-4 bg-transparent">
          <div className="max-w-4xl mx-auto">
            <form 
              onSubmit={handleSend}
              className="relative flex items-center gap-2"
            >
              <div className="relative flex-1 group">
                <input
                  type="text"
                  value={input}
                  onChange={(e) => setInput(e.target.value)}
                  placeholder={`Ask for ${bibleVersion} wisdom...`}
                  className="w-full bg-white border-2 border-slate-200 focus:border-indigo-500 focus:ring-0 rounded-2xl py-4 pl-6 pr-14 text-sm transition-all duration-200 shadow-md group-hover:shadow-lg outline-none"
                  disabled={isLoading}
                />
                <button
                  type="submit"
                  disabled={!input.trim() || isLoading}
                  className={`absolute right-3 top-1/2 -translate-y-1/2 w-10 h-10 rounded-xl flex items-center justify-center transition-all duration-200 ${
                    input.trim() && !isLoading 
                    ? 'bg-indigo-600 text-white scale-100 shadow-lg shadow-indigo-200 hover:bg-indigo-700' 
                    : 'bg-slate-100 text-slate-400 scale-90'
                  }`}
                >
                  <i className={`fa-solid ${isLoading ? 'fa-spinner fa-spin' : 'fa-paper-plane'}`}></i>
                </button>
              </div>
            </form>
            <p className="text-center text-[10px] text-slate-400 mt-3 font-medium uppercase tracking-tighter">
              Seek and you shall find &bull; {bibleVersion} Translation
            </p>
          </div>
        </div>
      </main>

      {/* Favorites Modal Overlay */}
      {showFavorites && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
