import { GoogleGenAI, Type } from "@google/genai";
import { GeminiResponse, BibleVersion } from "../types";

const getSystemInstruction = (version: BibleVersion) => `You are a wise and compassionate Bible scholar. 
Provide answers based strictly on Bible teachings using the ${version} translation. 
The 'answer' field MUST be extremely concise, approximately 10-15 words maximum.
The 'reference' should be the specific Bible verse used.
The 'topic' should be a single word describing the subject.
The 'explanation' field should provide 1-2 sentences of context.`;

/**
 * Helper to handle retries with exponential backoff for transient errors like 503
 */
const callWithRetry = async (fn: () => Promise<any>, maxRetries = 3): Promise<any> => {
  let lastError: any;
  for (let attempt = 0; attempt < maxRetries; attempt++) {
    try {
      return await fn();
    } catch (error: any) {
      lastError = error;
      const errorMsg = error.message || "";
      const isRetryable = errorMsg.includes("503") || 
                          errorMsg.includes("429") || 
                          errorMsg.includes("overloaded") ||
                          errorMsg.includes("fetch");

      if (isRetryable && attempt < maxRetries - 1) {
        const delay = Math.pow(2, attempt) * 1000 + Math.random() * 1000;
        await new Promise(resolve => setTimeout(resolve, delay));
        continue;
      }
      throw error;
    }
  }
  throw lastError;
};

export const getBibleWisdom = async (prompt: string, version: BibleVersion, customKey?: string): Promise<GeminiResponse> => {
  const apiKey = customKey || process.env.API_KEY || '';

  if (!apiKey) {
    return { 
      answer: "Error", 
      reference: "", 
      topic: "Config", 
      explanation: "", 
      error: "API Key is missing. Please provide one in settings to continue."
    };
  }

  try {
    const ai = new GoogleGenAI({ apiKey });

    const result = await callWithRetry(() => ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        systemInstruction: getSystemInstruction(version),
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            answer: {
              type: Type.STRING,
              description: `A very short biblical answer (10 words) in ${version}.`,
            },
            reference: {
              type: Type.STRING,
              description: "The Bible verse reference.",
            },
            topic: {
              type: Type.STRING,
              description: "Short topic.",
            },
            explanation: {
              type: Type.STRING,
              description: "1-2 sentence context.",
            },
          },
          required: ["answer", "reference", "topic", "explanation"],
        },
        temperature: 0.5,
      },
    }));

    const jsonStr = result.text || "{}";
    const data = JSON.parse(jsonStr);

    return {
      answer: data.answer || "No scriptural answer found.",
      reference: data.reference || "Unknown",
      topic: data.topic || "Wisdom",
      explanation: data.explanation || ""
    };
  } catch (error: any) {
    console.error("Gemini API Final Error:", error);

    let errorMessage = "The service is currently busy. Please wait a moment and try again.";

    const errorString = typeof error === 'string' ? error : JSON.stringify(error);
    if (errorString.includes("503") || errorString.includes("overloaded")) {
      errorMessage = "Google's AI servers are currently at capacity. Please try your question again in a few seconds.";
    } else if (errorString.includes("429")) {
      errorMessage = "Daily limit reached or service too busy. Consider providing your own API key in settings.";
    } else if (error.message && error.message.includes("fetch")) {
      errorMessage = "Connection lost. Please check your internet or VPN.";
    } else if (errorString.includes("403") || errorString.includes("API_KEY_INVALID")) {
      errorMessage = "The provided API Key is invalid. Please check your settings.";
    }

    return { 
      answer: "Connection Issue",
      reference: "",
      topic: "Error",
      explanation: "",
      error: errorMessage
    };
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { Message, SavedAnswer, BibleVersion, CreditState, UserSettings } from './types';
import { getBibleWisdom } from './services/geminiService';
import ChatMessage from './components/ChatMessage';

const BIBLE_VERSIONS: BibleVersion[] = ['NIV', 'KJV', 'ESV', 'NLT', 'NKJV', 'NASB'];
const DAILY_FREE_CREDITS = 5;

const App: React.FC = () => {
  const [messages, setMessages] = useState<Message[]>([
    {
      id: 'welcome',
      role: 'assistant',
      content: 'Welcome. What spiritual wisdom do you seek today?',
      timestamp: new Date()
    }
  ]);
  const [savedAnswers, setSavedAnswers] = useState<SavedAnswer[]>([]);
  const [bibleVersion, setBibleVersion] = useState<BibleVersion>('NIV');
  const [darkMode, setDarkMode] = useState(false);
  const [showFavorites, setShowFavorites] = useState(false);
  const [showSupport, setShowSupport] = useState(false);

  // Monetization & Limits State
  const [credits, setCredits] = useState<CreditState>({
    remaining: DAILY_FREE_CREDITS,
    lastReset: new Date().toISOString().split('T')[0]
  });
  const [userSettings, setUserSettings] = useState<UserSettings>({
    useCustomKey: false,
    customApiKey: ''
  });

  const [expandedSavedId, setExpandedSavedId] = useState<string | null>(null);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [lastError, setLastError] = useState<string | null>(null);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const scrollContainerRef = useRef<HTMLElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  // Load state from local storage
  useEffect(() => {
    const storedFavorites = localStorage.getItem('bible_favorites');
    if (storedFavorites) {
      try {
        const parsed = JSON.parse(storedFavorites);
        setSavedAnswers(parsed.map((item: any) => ({
          ...item,
          timestamp: new Date(item.timestamp)
        })));
      } catch (e) { console.error(e); }
    }

    const storedVersion = localStorage.getItem('bible_version');
    if (storedVersion && BIBLE_VERSIONS.includes(storedVersion as BibleVersion)) {
      setBibleVersion(storedVersion as BibleVersion);
    }

    const storedDarkMode = localStorage.getItem('bible_dark_mode');
    if (storedDarkMode === 'true') setDarkMode(true);

    const storedCredits = localStorage.getItem('bible_credits');
    if (storedCredits) {
      const parsed: CreditState = JSON.parse(storedCredits);
      const today = new Date().toISOString().split('T')[0];
      if (parsed.lastReset !== today) {
        setCredits({ remaining: DAILY_FREE_CREDITS, lastReset: today });
      } else {
        setCredits(parsed);
      }
    }

    const storedSettings = localStorage.getItem('bible_settings');
    if (storedSettings) setUserSettings(JSON.parse(storedSettings));
  }, []);

  // Persist state
  useEffect(() => { localStorage.setItem('bible_favorites', JSON.stringify(savedAnswers)); }, [savedAnswers]);
  useEffect(() => { localStorage.setItem('bible_version', bibleVersion); }, [bibleVersion]);
  useEffect(() => { localStorage.setItem('bible_dark_mode', darkMode.toString()); }, [darkMode]);
  useEffect(() => { localStorage.setItem('bible_credits', JSON.stringify(credits)); }, [credits]);
  useEffect(() => { localStorage.setItem('bible_settings', JSON.stringify(userSettings)); }, [userSettings]);

  const scrollToBottom = (instant = false) => {
    if (!scrollContainerRef.current) return;
    const container = scrollContainerRef.current;
    if (container.scrollHeight > container.clientHeight) {
      messagesEndRef.current?.scrollIntoView({ behavior: instant ? 'auto' : 'smooth', block: 'end' });
    }
  };

  useEffect(() => {
    const timer = setTimeout(() => {
      if (messages.length > 1 || isLoading) scrollToBottom();
    }, 100);
    return () => clearTimeout(timer);
  }, [messages, isLoading]);

  const handleSend = async (e?: React.FormEvent, retryInput?: string) => {
    e?.preventDefault();
    const textToSend = retryInput || input;
    if (!textToSend.trim() || isLoading) return;

    // Credit Check (Only if not using custom key)
    if (!userSettings.useCustomKey || !userSettings.customApiKey) {
      if (credits.remaining <= 0) {
        setLastError("Daily free wisdom limit reached. Support the app or provide your own API key to continue.");
        setShowSupport(true);
        return;
      }
    }

    setLastError(null);
    const userMessage: Message = { id: Date.now().toString(), role: 'user', content: textToSend, timestamp: new Date() };

    if (!retryInput) {
      setMessages(prev => [...prev, userMessage]);
      setInput('');
    }

    setIsLoading(true);

    try {
      const activeKey = userSettings.useCustomKey ? userSettings.customApiKey : undefined;
      const result = await getBibleWisdom(textToSend, bibleVersion, activeKey);

      if (result.error) throw new Error(result.error);

