                darkMode ? 'bg-slate-800 text-slate-200 hover:bg-slate-700' : 'bg-white text-slate-600 hover:bg-slate-50'
              }`}
            >
              <i className="fa-solid fa-bookmark text-indigo-500"></i>
              <span className="hidden sm:inline">Saved</span>
