          <p className={`text-center text-[9px] md:text-[10px] mt-2 font-medium uppercase tracking-tighter ${darkMode ? 'text-slate-500' : 'text-slate-400'}`}>
            Divine Wisdom in {bibleVersion} &bull; Always Accessible
