      const errorMsg = error.message || "";
      if ((errorMsg.includes("503") || errorMsg.includes("429")) && attempt < maxRetries - 1) {
        await new Promise(resolve => setTimeout(resolve, Math.pow(2, attempt) * 1000));
        continue;
      }
      throw error;
    }
  }
  throw lastError;
};

