                  <button onClick={() => setAiSettings({...aiSettings, provider: 'ollama'})} className={`py-2 rounded-lg text-xs font-bold transition-all ${aiSettings.provider === 'ollama' ? 'bg-white dark:bg-slate-700 shadow-sm' : 'text-slate-500'}`}>Local</button>
                </div>
              </div>

              {aiSettings.provider === 'gemini' && (
                <div className="space-y-4 animate-in slide-in-from-top-2">
                  <div>
                    <label className="text-[10px] font-bold text-slate-400 uppercase mb-1 block">Gemini API Key (Optional)</label>
                    <input 
                      type="password"
                      placeholder="Leave blank for server default"
                      value={aiSettings.geminiApiKey || ''} 
                      onChange={e => setAiSettings({...aiSettings, geminiApiKey: e.target.value})} 
                      className={`w-full p-3 text-xs rounded-xl border focus:ring-1 focus:ring-indigo-500 outline-none ${darkMode ? 'bg-slate-800 border-slate-700' : 'bg-slate-50 border-slate-200'}`} 
                    />
                    <p className="mt-1 text-[9px] text-slate-500 italic">Get your own key at <a href="https://ai.google.dev" target="_blank" rel="noreferrer" className="underline text-indigo-500">ai.google.dev</a></p>
                  </div>
                </div>
              )}

              {aiSettings.provider === 'ollama' && (
                <div className="space-y-4 animate-in slide-in-from-top-2">
                  <div>
                    <label className="text-[10px] font-bold text-slate-400 uppercase mb-1 block">Ollama Endpoint</label>
                    <input 
                      placeholder="http://localhost:11434"
                      value={aiSettings.ollamaHost} 
                      onChange={e => setAiSettings({...aiSettings, ollamaHost: e.target.value})} 
                      className={`w-full p-3 text-xs rounded-xl border ${darkMode ? 'bg-slate-800 border-slate-700' : 'bg-slate-50 border-slate-200'}`} 
                    />
                  </div>
                  <div>
                    <label className="text-[10px] font-bold text-slate-400 uppercase mb-1 block">Model Name</label>
                    <input 
                      placeholder="deepseek-r1:8b"
                      value={aiSettings.ollamaModel} 
                      onChange={e => setAiSettings({...aiSettings, ollamaModel: e.target.value})} 
                      className={`w-full p-3 text-xs rounded-xl border ${darkMode ? 'bg-slate-800 border-slate-700' : 'bg-slate-50 border-slate-200'}`} 
                    />
                  </div>
                  <div className="p-3 rounded-xl bg-amber-500/10 border border-amber-500/20 text-[10px] text-amber-600 leading-relaxed">
                    <strong>Fix for "Failed to Fetch":</strong> Browsers block cross-origin requests by default. 
                    Run Ollama with <code>OLLAMA_ORIGINS="*"</code> set in your environment variables.
                  </div>
                </div>
              )}
            </div>
            <button onClick={() => setShowSettings(false)} className="w-full mt-6 py-3 bg-indigo-600 text-white rounded-xl font-bold shadow-lg shadow-indigo-200 active:scale-95 transition-all">Save & Close</button>
          </div>
        </div>
      )}

      {/* Favorites Modal */}
      {showFavorites && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
          <div className={`w-full max-w-lg max-h-[80vh] overflow-hidden flex flex-col rounded-3xl ${darkMode ? 'bg-slate-900 border border-slate-800' : 'bg-white'}`}>
            <div className="p-6 border-b flex justify-between items-center">
              <h2 className="font-serif text-xl font-bold">Saved Wisdom</h2>
              <button onClick={() => setShowFavorites(false)} className="text-slate-400 hover:text-slate-600 transition-colors"><i className="fa-solid fa-xmark"></i></button>
            </div>
            <div className="flex-1 overflow-y-auto p-4 space-y-4">
              {savedAnswers.length === 0 ? <p className="text-center text-slate-400 py-10 text-sm">No saved verses yet.</p> : savedAnswers.map(s => (
                <div key={s.id} className={`p-4 rounded-2xl border transition-all ${darkMode ? 'bg-slate-800 border-slate-700' : 'bg-slate-50 border-slate-100'}`}>
                  <div className="flex justify-between items-center mb-1"><span className="text-[10px] font-bold text-indigo-500 uppercase">{s.topic}</span><button onClick={() => setSavedAnswers(p => p.filter(x => x.id !== s.id))} className="text-rose-500 hover:text-rose-600"><i className="fa-solid fa-trash text-xs"></i></button></div>
                  <p className="text-sm font-medium mb-1 leading-relaxed">{s.answer}</p>
                  <p className="text-[10px] text-slate-500 font-bold">— {s.reference} ({s.version})</p>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;
